css:
/* Raben design kit for MxScout v2: the Raben Design System stylesheet (artifact source of the RabenDesign module, without fonts), the module's rb-i-* icon classes and the License 2.0 prototype page layout; the v1 rules first for older mockups. */
:host { all: initial; }
.mk-mock { --rb-red-25: #fef9f9; --rb-red-200: #f49a9f; --rb-red-500: #e30311; --rb-neutral-25: #f7f7f7; --rb-neutral-50: #f3f3f3; --rb-neutral-700: #69696c;
  --rb-line: #e6e6e6; --rb-text: #000; --rb-text-2: #69696c; --rb-surface: #fff; --rb-positive-500: #0a6d3e; --rb-negative-500: #d9412b; --rb-attentive-500: #faa12a; --rb-info-600: #165eb9; }
.mk-mock { font: 400 14px/1.45 Barlow, "Segoe UI", system-ui, sans-serif; color: #000; background: #f7f7f7; padding: 16px; min-height: 120px; box-sizing: border-box; }
.mk-mock *, .mk-mock *::before, .mk-mock *::after { box-sizing: border-box; }
.mk-mock h1, .mk-mock h2, .mk-mock h3, .mk-mock h4 { font-weight: 600; margin: 0 0 10px; color: #000; }
.mk-mock h1 { font-size: 24px; } .mk-mock h2 { font-size: 20px; } .mk-mock h3 { font-size: 17px; } .mk-mock h4 { font-size: 15px; }
.mk-mock p { margin: 0 0 8px; }
.mk-mock .text-detail, .mk-mock small, .mk-mock .muted { color: #69696c; }
/* layout: header bar, page title, cards, rows */
.mk-mock .rb-header, .mk-mock .topbar { display: flex; align-items: center; gap: 12px; background: #fff; border-bottom: 3px solid #e30311; padding: 10px 16px; margin: -16px -16px 16px; font-weight: 600; }
.mk-mock .rb-logo { color: #e30311; font-weight: 700; letter-spacing: .04em; }
.mk-mock .card, .mk-mock .rb-card, .mk-mock .mx-groupbox { background: #fff; border: 1px solid #e6e6e6; border-radius: 8px; padding: 16px; margin: 0 0 16px; }
.mk-mock .card-title, .mk-mock .mx-groupbox-header { font-weight: 600; font-size: 15px; margin: 0 0 10px; }
.mk-mock .row { display: flex; flex-wrap: wrap; gap: 16px; }
.mk-mock .row > [class*="col"] { flex: 1 1 0; min-width: 160px; }
.mk-mock .col-3 { flex: 0 0 calc(25% - 12px); } .mk-mock .col-4 { flex: 0 0 calc(33.33% - 11px); } .mk-mock .col-6 { flex: 0 0 calc(50% - 8px); }
.mk-mock .toolbar, .mk-mock .btn-group, .mk-mock .rb-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 0 0 12px; }
.mk-mock .spacer, .mk-mock .ml-auto { margin-left: auto; }
/* buttons */
.mk-mock .btn, .mk-mock button { display: inline-flex; align-items: center; gap: 6px; font: 600 14px/1 inherit; font-family: inherit; padding: 9px 16px; border-radius: 4px; border: 1px solid #e6e6e6; background: #fff; color: #000; cursor: default; }
.mk-mock .btn-primary { background: #e30311; border-color: #e30311; color: #fff; }
.mk-mock .btn-success { background: #0a6d3e; border-color: #0a6d3e; color: #fff; }
.mk-mock .btn-danger { background: #d9412b; border-color: #d9412b; color: #fff; }
.mk-mock .btn-warning { background: #faa12a; border-color: #faa12a; color: #000; }
.mk-mock .btn-link { background: transparent; border-color: transparent; color: #e30311; padding-left: 0; padding-right: 0; }
.mk-mock .btn-sm { padding: 6px 10px; font-size: 13px; }
/* forms */
.mk-mock .form-group { margin: 0 0 12px; }
.mk-mock label, .mk-mock .control-label { display: block; font-weight: 600; font-size: 13px; margin: 0 0 4px; }
.mk-mock .form-control, .mk-mock input:not([type="checkbox"]):not([type="radio"]), .mk-mock select, .mk-mock textarea { display: block; width: 100%; font: inherit; padding: 8px 10px; border: 1px solid #e6e6e6; border-radius: 4px; background: #fff; color: #000; }
.mk-mock [disabled], .mk-mock [readonly] { background: #f3f3f3; }
.mk-mock .form-horizontal .form-group { display: grid; grid-template-columns: 180px 1fr; gap: 10px; align-items: center; }
.mk-mock .help-block, .mk-mock .validation { font-size: 12px; color: #69696c; margin-top: 4px; }
.mk-mock .has-error .form-control, .mk-mock .is-invalid { border-color: #d9412b; }
.mk-mock .has-error .help-block, .mk-mock .validation.error { color: #d9412b; }
/* data grid */
.mk-mock table, .mk-mock .table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e6e6e6; border-radius: 8px; overflow: hidden; }
.mk-mock th { text-align: left; font-weight: 600; font-size: 13px; color: #69696c; background: #fafafa; }
.mk-mock th, .mk-mock td { padding: 10px 12px; border-bottom: 1px solid #e6e6e6; }
.mk-mock tr:last-child td { border-bottom: 0; }
.mk-mock tr.selected td, .mk-mock tr.active td { background: #fef9f9; }
.mk-mock .pagination, .mk-mock .datagrid-footer { display: flex; justify-content: flex-end; gap: 8px; padding: 8px 0; color: #69696c; font-size: 13px; }
/* badges, alerts, tabs */
.mk-mock .badge, .mk-mock .label { display: inline-block; font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 32px; background: #e5e5e5; color: #000; }
.mk-mock .badge-success, .mk-mock .label-success { background: #f8fcf6; color: #0a6d3e; border: 1px solid #c8ddbe; }
.mk-mock .badge-danger, .mk-mock .label-danger { background: #f6eeec; color: #d9412b; border: 1px solid #eeaa9f; }
.mk-mock .badge-warning, .mk-mock .label-warning { background: #f9f5ea; color: #8a5a00; border: 1px solid #e2dbc2; }
.mk-mock .badge-primary, .mk-mock .label-primary { background: #fef9f9; color: #e30311; border: 1px solid #f49a9f; }
.mk-mock .alert { padding: 10px 14px; border-radius: 4px; border: 1px solid #e6e6e6; margin: 0 0 12px; background: #fff; }
.mk-mock .alert-danger { background: #f6eeec; border-color: #eeaa9f; } .mk-mock .alert-success { background: #f8fcf6; border-color: #c8ddbe; }
.mk-mock .alert-warning { background: #f9f5ea; border-color: #e2dbc2; } .mk-mock .alert-info, .mk-mock .alert-primary { background: #fef9f9; border-color: #f49a9f; }
.mk-mock .nav-tabs, .mk-mock .tabs { display: flex; gap: 4px; border-bottom: 1px solid #e6e6e6; margin: 0 0 12px; padding: 0; list-style: none; }
.mk-mock .nav-tabs > *, .mk-mock .tabs > * { padding: 8px 14px; color: #69696c; }
.mk-mock .nav-tabs > .active, .mk-mock .tabs > .active { color: #000; font-weight: 600; border-bottom: 2px solid #e30311; margin-bottom: -1px; }
.mk-mock hr { border: 0; border-top: 1px solid #e6e6e6; margin: 12px 0; }
/* shell: sidebar + top bar + content (module _layouts.scss) */
.mk-mock .raben-layout { display: grid; grid-template-columns: 200px 1fr; margin: -16px; min-height: 260px; background: var(--rb-neutral-25); }
.mk-mock .raben-sidebar { background: #fff; border-right: 1px solid var(--rb-line); padding: 12px 0; }
.mk-mock .raben-sidebar > * { display: block; padding: 8px 16px; color: var(--rb-text-2); }
.mk-mock .raben-sidebar > .active { color: var(--rb-red-500); font-weight: 600; background: var(--rb-red-25); border-left: 3px solid var(--rb-red-500); }
.mk-mock .raben-topbar { display: flex; align-items: center; gap: 12px; background: #fff; border-bottom: 1px solid var(--rb-line); padding: 12px 24px; font-weight: 600; }
.mk-mock .raben-content { padding: 24px; }
/* KPI tiles, key–value lists, search, empty state */
.mk-mock .rb-kpi { background: #fff; border: 1px solid var(--rb-line); border-radius: 8px; padding: 16px; flex: 1 1 0; min-width: 140px; }
.mk-mock .rb-kpi .value { font-size: 28px; font-weight: 600; line-height: 1.1; } .mk-mock .rb-kpi .caption { color: var(--rb-text-2); font-size: 13px; }
.mk-mock .rb-kv { display: grid; grid-template-columns: 160px 1fr; gap: 6px 12px; margin: 0 0 12px; } .mk-mock .rb-kv dt { color: var(--rb-text-2); } .mk-mock .rb-kv dd { margin: 0; }
.mk-mock .rb-search { max-width: 280px; } .mk-mock .rb-empty { text-align: center; color: var(--rb-text-2); padding: 32px 16px; }
.mk-mock .rb-placeholder { border: 1px dashed var(--rb-line); border-radius: 4px; padding: 10px; color: var(--rb-text-2); font-size: 13px; background: #fff; }

/* The accent the viewer around a mockup reads (forbusiness.js: --v-red is var(--mk-primary)), so the frame of the
   clickable prototype — its menu, its buttons, its focus rings — carries this design's red too, not the default. */
:root, .mk-mock { --mk-primary: #e30311; --mk-primary-soft: #fef9f9; }

/* the names the neutral kit writes, drawn as this design draws its own */
.mk-mock .mk-header { display: flex; align-items: center; gap: 10px; background: #fff; border-bottom: 1px solid #e6e6e6; padding: 10px 16px; margin: -16px -16px 16px; font-weight: 600; }
.mk-mock .mk-brand { color: #e30311; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
.mk-mock .mk-kpi { flex: 1 1 140px; background: #fff; border: 1px solid #e6e6e6; border-radius: 8px; padding: 14px 16px; }
.mk-mock .mk-kpi .value { font-size: 26px; font-weight: 700; line-height: 1.1; }
.mk-mock .mk-kpi .caption { color: #69696c; font-size: 12.5px; }
.mk-mock .mk-search { max-width: 280px; }
.mk-mock .app-layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); min-height: 320px; margin: -16px; background: #fff; }
.mk-mock .app-sidebar { display: flex; flex-direction: column; gap: 2px; background: #fff; border-right: 1px solid #e6e6e6; padding: 12px 8px; }
.mk-mock .app-sidebar span { padding: 8px 12px; border-radius: 4px; color: #000; }
.mk-mock .app-sidebar span.active { background: #fef9f9; color: #e30311; font-weight: 600; }
.mk-mock .app-topbar { display: flex; align-items: center; gap: 12px; border-bottom: 1px solid #e6e6e6; padding: 12px 20px; font-weight: 600; }
.mk-mock .app-content { padding: 20px; background: #f7f7f7; min-height: 240px; }
