.mk-mock{font: 400 var(--rb-fs-b3) / var(--rb-lh-b3) var(--rb-font);color: var(--rb-text);background: var(--rb-bg);-webkit-font-smoothing: antialiased}.lp-page{display: flex;flex-direction: column;gap: 16px;padding: 24px;box-sizing: border-box}.lp-page > *{margin: 0}.lp-page [hidden]{display: none !important}.btn-sm, .widget-datagrid-header .btn{text-transform: none;letter-spacing: 0}.lp-head .link-back{margin-bottom: 8px}.lp-crumbs{font: 500 var(--rb-fs-b4) / var(--rb-lh-b4) var(--rb-font);color: var(--rb-text-2);margin-bottom: 4px}.lp-sub{margin: 8px 0 0;font: 600 var(--rb-fs-b2) / var(--rb-lh-b2) var(--rb-font)}.lp-split{display: grid;grid-template-columns: minmax(300px, 380px) minmax(0, 1fr);gap: 16px;align-items: start}.lp-stack{display: flex;flex-direction: column;gap: 12px;min-width: 0}.lp-note{margin: 0;font-size: var(--rb-fs-b4)}.lp-err{color: var(--rb-tag-negative-text, var(--rb-red-500))}.lp-alert-dot{display: inline-block;width: 8px;height: 8px;border-radius: 50%;background: var(--rb-red-500);box-shadow: 0 0 0 3px var(--rb-red-50)}.lp-search{display: flex;gap: 8px;align-items: center}.lp-search .form-control{width: 220px}.lp-page .widget-datagrid-content{overflow-x: auto}.lp-page .widget-datagrid-header{flex-wrap: wrap}.widget-datagrid.lp-noalert .th.rb-col-id, .widget-datagrid.lp-noalert .td.rb-col-id{left: 0}.lp-wrapcells .td, .lp-wrapcells .td > span{white-space: normal}.lp-wrapcells .tr:not(.rb-head) .td{padding-block: 10px}.lp-scroll{overflow-x: auto}.lp-table{width: 100%}.lp-table td, .lp-table th{vertical-align: middle}.lp-tabs{margin: 0}.lp-tabpanel{display: flex;flex-direction: column;gap: 16px}.lp-modal-mock{display: flex;justify-content: center;padding: 32px 24px;background: var(--rb-backdrop)}.lp-modal-mock .modal-dialog{max-height: none}.lp-modal .modal-body{flex-direction: column;align-items: stretch;justify-content: flex-start;background: var(--rb-surface);min-height: 0}.lp-modal.rb-confirm .modal-body{flex-direction: row;align-items: flex